select pg_temp.pub(ali,kad,5,'18:00','22:00',7), pg_temp.pub(mk_e,kad,6,'18:00','22:00',8), pg_temp.pub(ali,kad,2,'10:00','14:00',3), pg_temp.pub(ayse,bes,3,'10:00','14:00',4) from fx;
create temp table st(k text primary key, v jsonb);
-- E4: Ali offers Kadikoy S7 directly to Ayse (assigned to Kadikoy+Besiktas)
insert into st select 'e4', pg_temp.cmd(ali_u,jsonb_build_object('action','create','kind','cover','shift_id',pg_temp.sid(7),'employee_id',ayse)) from fx;
insert into st select 'e4a', pg_temp.cmd(ayse_u,jsonb_build_object('action','accept','case_id',(select v->>'case_id' from st where k='e4'),'application_id',(select id from public.shift_exchange_applications where case_id=(select (v->>'case_id')::uuid from st where k='e4')),'expected_revision',(select (v->>'revision')::int from st where k='e4'))) from fx;
select 'E4 MB (Besiktas mgr) preview on Kadikoy cover', pg_temp.try(format($q$select public.shift_exchange_preview(%L,%L,%L,(select id from public.shift_exchange_applications where case_id=%L))::text$q$,mb_u,w,(select v->>'case_id' from st where k='e4'),(select v->>'case_id' from st where k='e4'))) from fx;
select 'E4 MK preview', public.shift_exchange_preview(mk_u,w,c.id,a.id)->>'requires_other_manager' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e4');
select 'E4 MK approve', pg_temp.cmd(mk_u,jsonb_build_object('action','approve','case_id',c.id,'application_id',a.id,'expected_revision',c.revision,'fingerprint',public.shift_exchange_preview(mk_u,w,c.id,a.id)->>'fingerprint'))->>'status' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e4');
-- E6: manager Kemal (own employee record) offers own shift S8 to Ali, then tries to approve it
insert into st select 'e6', pg_temp.cmd(mk_u,jsonb_build_object('action','create','kind','cover','shift_id',pg_temp.sid(8),'employee_id',ali)) from fx;
select 'E6 manager created own cover', v from st where k='e6';
select pg_temp.cmd(ali_u,jsonb_build_object('action','accept','case_id',c.id,'application_id',a.id,'expected_revision',c.revision)) from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e6');
select 'E6 MK self preview reasons', public.shift_exchange_preview(mk_u,w,c.id,a.id)->'reasons' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e6');
select 'E6 owner approves', pg_temp.cmd(owner_u,jsonb_build_object('action','approve','case_id',c.id,'application_id',a.id,'expected_revision',c.revision,'fingerprint',public.shift_exchange_preview(owner_u,w,c.id,a.id)->>'fingerprint'))->>'status' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e6');
-- E7: cross-location swap S3(K)<->S4(B); owner approves once
insert into st select 'e7', pg_temp.cmd(ali_u,jsonb_build_object('action','create','kind','swap','shift_id',pg_temp.sid(3),'requested_shift_id',pg_temp.sid(4))) from fx;
select pg_temp.cmd(ayse_u,jsonb_build_object('action','accept','case_id',c.id,'application_id',a.id,'expected_revision',c.revision)) from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e7');
select 'E7 MK approve (one of two)', pg_temp.cmd(mk_u,jsonb_build_object('action','approve','case_id',c.id,'application_id',a.id,'expected_revision',c.revision,'fingerprint',public.shift_exchange_preview(mk_u,w,c.id,a.id)->>'fingerprint'))->>'status' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e7');
select 'E7 owner approve (completes?)', pg_temp.cmd(owner_u,jsonb_build_object('action','approve','case_id',c.id,'application_id',a.id,'expected_revision',c.revision,'fingerprint',public.shift_exchange_preview(owner_u,w,c.id,a.id)->>'fingerprint'))->>'status' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.id=(select (v->>'case_id')::uuid from st where k='e7');
-- E8: owner's own employee record can pick up / be offered; owner self-approve?
select 'E8 owner creates cover of nothing (owner has no shift) -> apply to open shift', pg_temp.pub(null,kad,6,'10:00','14:00',9) from fx;
select 'E8 owner applies to open shift', pg_temp.try(format($q$select pg_temp.cmd(%L,jsonb_build_object('action','apply','shift_id',%L))::text$q$,owner_u,pg_temp.sid(9))) from fx;
select 'E8 owner self preview', public.shift_exchange_preview(owner_u,w,c.id,a.id)->'reasons' from fx, public.shift_exchange_cases c join public.shift_exchange_applications a on a.case_id=c.id where c.offered_source_id=pg_temp.sid(509);
